  private import ScalarValues::*;
  part def Controller {
    in attribute io_0 : Integer;
    attribute accumulatedMs : Integer := 0;
    attribute displayValue : Integer := 0;
    perform action tick {
      first start;
      then assign accumulatedMs := accumulatedMs + io_0;
      then if ((accumulatedMs) >= (1000)) {
        first start;
        then assign accumulatedMs := accumulatedMs - 1000;
        then assign displayValue := displayValue + 1;
      }
    }
    out attribute io_1 : Integer = displayValue;
  }
  part system : Controller;
}
